20	/**
21	 * Streams rows into the table defined by schema/events.md's BigQuery DDL.
22	 * Requires the optional peer dependency `@google-cloud/bigquery` —
23	 * dynamically imported so it isn't required unless this sink is actually
24	 * used. Credentials come from Application Default Credentials, same as the
25	 * client library's own defaults.
26	 */
27	export function bigquerySink(options: BigQuerySinkOptions = {}): Sink {
28	  const dataset = options.dataset ?? 'mcpsignals';
29	  const toolCallTable = options.toolCallTable ?? 'tool_call';
30	
31	  let clientPromise: Promise<BigQueryClient> | undefined;
32	
33	  async function getClient(): Promise<BigQueryClient> {
34	    if (!clientPromise) {
35	      clientPromise = (async () => {
36	        if (options.client) {
37	          return options.client as BigQueryClient;
38	        }
39	        const mod = await import('@google-cloud/bigquery');
40	        const BigQuery = mod.BigQuery;
41	        return new BigQuery(
42	          options.projectId ? { projectId: options.projectId } : undefined
43	        ) as unknown as BigQueryClient;
44	      })();
45	    }
46	    return clientPromise;
47	  }
48	
49	  return {
50	    async write(events: AnyEvent[]): Promise<void> {
51	      const client = await getClient();
52	      const toolCalls = events.filter(
53	        (e): e is Extract<AnyEvent, { event_type: 'tool_call' }> => e.event_type === 'tool_call'
54	      );
55	      if (toolCalls.length > 0) {
56	        await client
57	          .dataset(dataset)
58	          .table(toolCallTable)
59	          .insert(
60	            toolCalls.map(e => ({
61	              ts: e.ts.toISOString(),
62	              server_name: e.server_name,
63	              server_version: e.server_version,
